package com.bank.ro.repository;

import com.bank.ro.model.Account;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.Optional;

public interface AccountRepository extends JpaRepository<Account, String> {

    // fetch-join loads txns in ONE query inside the service transaction
    @Query("select a from Account a left join fetch a.txns where a.id = :id")
    Optional<Account> findWithTxns(@Param("id") String id);
}
