package com.bank.ro.service;

import com.bank.ro.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Slf4j
@Service
@RequiredArgsConstructor
public class BalanceService {
    private final AccountRepository repo;

    // readOnly=true → no dirty checking, connection read-only (replica routing)
    @Transactional(readOnly = true)
    public BigDecimal balanceOf(String id) {
        BigDecimal bal = repo.findById(id).orElseThrow().getBalance();
        log.info("Balance enquiry {} = {}", id, bal);
        return bal;  // Hibernate performs NO flush / snapshot comparison
    }
}
