package com.bank.ro.service;

import com.bank.ro.model.*;
import com.bank.ro.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class StatementService {
    private final AccountRepository repo;

    // Fetch everything inside the transaction (no OSIV reliance, no N+1)
    @Transactional(readOnly = true)
    public List<Txn> statement(String id) {
        Account acc = repo.findWithTxns(id).orElseThrow();  // single fetch-join query
        List<Txn> txns = acc.getTxns();                      // already initialized
        log.info("Statement {} loaded {} txns in ONE query", id, txns.size());
        return txns;  // controller/view gets initialized data, session can close
    }
}
